/*  🍓转账卡片 by小Q怡 */
/* =================================== */
:root{
  --transfer-card-bg:#FA9D3B;
  --transfer-card-bg-received:#FCE2BC;
  --transfer-card-bg-expired:#E6C7A5;
  --transfer-icon-default:url('https://i.postimg.cc/j5CqLH5J/wu-biao-ti38-20260205143013.png');
  --transfer-icon-received:url('https://nos.netease.com/ysf/032ae26e2e69a232d3bb904047b34e38.png');
  --transfer-icon-returned:url('https://nos.netease.com/ysf/0b5a28d77f1934fdcc6750fd8f9897c6.png');
  --transfer-icon-expired:url('https://nos.netease.com/ysf/dfbb30c0b7383f9209c03597b101adfe.png');
