  max-width:none !important;
}

/* 名字：加粗，前面补「回复」两个字 */
.msg-reply-block-name{
  font-size:13px !important;
  font-weight:700 !important;
  line-height:18px !important;
  color:var(--nj-q-name) !important;
}
.msg-reply-block-name::before{
  content:"回复\00a0";
}

/* 被引用的文字 */
.msg-reply-block-text{
  font-size:13px !important;
  line-height:18px !important;
  color:var(--nj-q-text) !important;
  opacity:1 !important;
}

/* ===== 思维链 → 名字===== */
:root{
  .nuo-thinking-label::before{
  content: var(--char-name);   /* 当前角色名，自动跟着聊天对象走 */
  font-size:13px;
  font-weight:700;
  color:var(--nj-q-name);
}

  --thinking-btn-bg:transparent;
  --thinking-btn-border:none;
  --thinking-btn-shadow:none;
  --thinking-btn-padding:0;
}

.nuo-thinking-btn{
  background:none !important;
  border:none !important;
  box-shadow:none !important;
  padding:0 !important;
}

/* 藏掉 ▶ 和 💭 */
.nuo-thinking-arrow,
.nuo-thinking-icon{
  display:none !important;
}

/* 原文字"思维链"藏掉，换成名字 */
.nuo-thinking-label{
  font-size:0 !important;
}
.nuo-thinking-label::before{
  content:var(--char-name);
  font-size:13px;
  font-weight:700;
}

